extern "C" int strlen(const char *);

struct string_buf {
  int refs;
  int alloc;
  int char_length;
};

class stringx {
public:
  char *chars;
  string_buf *my_buf;

  stringx() __asm__("__7stringx");
  stringx(const stringx &) __asm__("__7stringxRC7stringx");
  ~stringx() __asm__("_$_7stringx");
  void make_room(int) __asm__("make_room__7stringxi");
  void append(const stringx &) __asm__("append__7stringxRC7stringx");
  void append(const char *, int) __asm__("append__7stringxPCci");
};

inline stringx operator+(const char *lhs, const stringx &rhs) {
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx &lhs, const stringx &rhs) {
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

extern void error(const stringx &) __asm__("error__FRC7stringx");

struct num_list {
  int *begin_value;
};

struct instance {
  stringx name;
};

struct executable {
  int unused[3];
  stringx fullname;
};

struct vm_thread {
  instance *inst;
  executable *ex;
};

class vm_stack {
public:
  int salloc;
  char *buffer;
  char *SP;
  vm_thread *my_thread;

  bool push(const char *, int) __asm__("push__8vm_stackPCci");
};

struct entry_t {
  int value;
};

bool function(vm_stack &stack, entry_t)
  __asm__("__cl__20slf_num_list_begin_tR8vm_stackQ320script_library_class8function7entry_t");

bool function(vm_stack &stack, entry_t) {
  stack.SP -= 4;
  num_list *me = *(num_list **)stack.SP;
  int *result = me->begin_value;
  if (!stack.push((char *)&result, sizeof(result)))
    error(stack.my_thread->inst->name + ": stack overflow in " +
          stack.my_thread->ex->fullname);
  return true;
}
